// Server-only HTTP client for the Mod Builder build service (build VM).
//
// Config, first hit wins:
//   env MODBUILDER_URL / MODBUILDER_API_KEY
//   file $MODBUILDER_ENV_FILE (default /etc/nxeon/modbuilder.env, root:nxeon 0640 so the web user can read it), KEY=VALUE lines
// The URL is the primary-side end of the SSH tunnel
// (nxeon-modbuilder-tunnel.service: 127.0.0.1:7340 -> VM 127.0.0.1:7340).
//
// Cyrus capacity (scale-out readiness): CYRUS_MB_DISPATCH=1 + MODBUILDER_URLS (two or more) spreads builds over N workers
// (lib/cyrus/builder/dispatch.ts: placement by /health load, sticky per build id, a change follows its base build).
// Off (the default) = the single MODBUILDER_URL exactly as before.
import { readFileSync } from "node:fs";
import { cyrusConfig } from "../config";
import { createDispatcher, dispatchWorkers, type Dispatcher, type WorkerHealth } from "./dispatch";

type Cfg = { url: string; key: string };
let cached: { cfg: Cfg | null; at: number } | null = null;

export function modBuilderConfig(): Cfg | null {
  if (cached && Date.now() - cached.at < 60_000) return cached.cfg;
  let url = process.env.MODBUILDER_URL || "";
  let key = process.env.MODBUILDER_API_KEY || "";
  if (!url || !key) {
    try {
      const text = readFileSync(cyrusConfig().modbuilderEnvFile, "utf8");
      for (const line of text.split("\n")) {
        const m = line.match(/^\s*([A-Z_]+)\s*=\s*(.*)\s*$/);
        if (!m) continue;
        if (m[1] === "MODBUILDER_URL" && !url) url = m[2];
        if (m[1] === "MODBUILDER_API_KEY" && !key) key = m[2];
      }
    } catch { /* not configured */ }
  }
  const cfg = url && key ? { url: url.replace(/\/+$/, ""), key } : null;
  cached = { cfg, at: Date.now() };
  return cfg;
}

export class ModBuilderUnavailable extends Error {}
/** Cyrus capacity: the build service refused a NEW build for capacity (line full, account busy). Retryable, nothing started. */
export class ModBuilderBusy extends Error {
  constructor(message: string, readonly code: string, readonly retryAfterSec: number | null) { super(message); }
}

let dispatcher: { d: Dispatcher | null; key: string; at: number } | null = null;

