      case "shade": ops.push({ op: "shade", amount: num(p.amount, 0, 60) ? p.amount : 28 }); break;
      case "outline": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "outline", c: p.c }); break;
      default: return { ok: false, error: `${at}: unknown op ${String(p.op)}` };
    }
  }
  return { ok: true, spec: { name: r.name, size, palette, mirror: r.mirror === true, ops } };
}

